import * as THREE from 'three/webgpu';
import { texture, positionGeometry, normalGeometry, mul, add } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load textures via cached loader
  const colorTexture = ctx.textureLoader.load(config.assets.imageUrl);
  const depthTexture = ctx.textureLoader.load(config.assets.depthMapUrl);

  // Create tessellated plane for displacement mapping
  const geometry = new THREE.PlaneGeometry(2.5, 0.3, 64, 64);

  // Build TSL displacement nodes
  const colorNode = texture(colorTexture);
  const displacementMap = texture(depthTexture);
  const displacementStrength = 0.06;
  const displacement = mul(displacementMap.r, displacementStrength);
  const displacedPosition = add(positionGeometry, mul(normalGeometry, displacement));

  // Create material with machined-metal PBR
  const material = new THREE.MeshStandardNodeMaterial({
    metalness: 0.48,
    roughness: 0.56,
    clearcoat: 0.18,
  });

  material.colorNode = colorNode;
  material.positionNode = displacedPosition;

  // Create and position mesh
  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(
    config.scenePosition[0],
    config.scenePosition[1],
    config.scenePosition[2]
  );
  mesh.scale.set(config.scale[0], config.scale[1], config.scale[2]);

  group.add(mesh);

  // Store initial state
  const initialPosition = mesh.position.clone();
  const initialScale = new THREE.Vector3(config.scale[0], config.scale[1], config.scale[2]);

  // Hover animation (rise-in: subtle 0.15 units)
  const hoverTimeline = gsap.timeline({ paused: true });
  hoverTimeline.to(mesh.position, {
    y: initialPosition.y + 0.15,
    duration: 0.7,
    ease: 'power3.out',
  }, 0);
  hoverTimeline.to(material, {
    clearcoat: 0.28,
    duration: 0.7,
    ease: 'power3.out',
  }, 0);

  // Click animation (press-down)
  const clickTimeline = gsap.timeline();
  clickTimeline.to(mesh.scale, {
    x: 0.97,
    y: 0.97,
    z: 0.97,
    duration: 0.12,
    ease: 'back.out',
  }).to(mesh.scale, {
    x: initialScale.x,
    y: initialScale.y,
    z: initialScale.z,
    duration: 0.3,
    ease: 'power2.out',
  });

  // Subtle time-based parallax effect
  const parallaxTimeline = gsap.timeline({ repeat: -1 });
  parallaxTimeline
    .to(mesh.rotation, { y: 0.015, duration: 4, ease: 'sine.inOut' }, 0)
    .to(mesh.rotation, { y: -0.015, duration: 4, ease: 'sine.inOut' }, 4);

  // Attach event handlers
  group.userData.handlers = {
    onHoverEnter: () => {
      hoverTimeline.play();
    },
    onHoverExit: () => {
      hoverTimeline.reverse();
    },
    onClick: () => {
      clickTimeline.restart();
      group.dispatchEvent({ type: 'hub-features.select' });
    },
  };

  // Cleanup function
  group.userData.cleanup = () => {
    hoverTimeline.kill();
    clickTimeline.kill();
    parallaxTimeline.kill();
    geometry.dispose();
    material.dispose();
    colorTexture.dispose();
    depthTexture.dispose();
  };

  return group;
}
